def calculate_material_properties():
    """
    Calculate material properties using Pymatgen.

    Returns:
        dict: A dictionary mapping each property name to its computed value.
              If a property cannot be computed, its value is set to None.
    """
    properties = {
        "defect_type": None,
        "replaced_atoms_set_1": None,
        "replaced_atoms_set_2": None
    }

    try:
        # Load the GaN structure
        file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")
        gan_struct = Structure.from_file(file_path / "GaN.vasp")

        # Check defect type for substitution {"Ga": ["Mg", "Ca"]}
        substitution_1 = {"Ga": ["Mg", "Ca"]}
        sub_gen_1 = SubstitutionGenerator(gan_struct, substitution_1)
        defects_1 = list(sub_gen_1.enumerate())
        properties["defect_type"] = all(defect.defect_type == "Substitution" for defect in defects_1)

        # Verify replaced atoms set for substitution {"Ga": ["Mg", "Ca"]}
        properties["replaced_atoms_set_1"] = set(substitution_1["Ga"])

        # Verify replaced atoms set for substitution {"Ga": "Mg"}
        substitution_2 = {"Ga": "Mg"}
        properties["replaced_atoms_set_2"] = set([substitution_2["Ga"]])

    except Exception as e:
        # If any error occurs, the corresponding property will remain None
        pass

    return properties

def calculate_vacancy_properties():
    """
    Calculate various properties of a vacancy defect in a GaN structure using Pymatgen.

    Returns:
        dict: A dictionary mapping property names to their computed values.
    """
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.core import Vacancy
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files")
    try:
        gan_struct = Structure.from_file(file_path / "GaN.vasp")
    except Exception as e:
        return {prop: None for prop in [
            "symmetry_equivalence", "vacancy_string_representation", "vacancy_oxidation_state",
            "vacancy_charge_states", "vacancy_multiplicity", "vacancy_supercell_formula",
            "vacancy_name", "vacancy_self_equivalence", "vacancy_element_changes", "vacancy_latex_name"
        ]}

    try:
        s = gan_struct.copy()
        vac = Vacancy(s, s.sites[0])
        vac2 = Vacancy(s, s.sites[1])
    except Exception as e:
        return {prop: None for prop in [
            "symmetry_equivalence", "vacancy_string_representation", "vacancy_oxidation_state",
            "vacancy_charge_states", "vacancy_multiplicity", "vacancy_supercell_formula",
            "vacancy_name", "vacancy_self_equivalence", "vacancy_element_changes", "vacancy_latex_name"
        ]}

    properties = {}

    try:
        properties["symmetry_equivalence"] = vac.is_symmetry_equivalent(vac2)
    except Exception:
        properties["symmetry_equivalence"] = None

    try:
        properties["vacancy_string_representation"] = str(vac)
    except Exception:
        properties["vacancy_string_representation"] = None

    try:
        properties["vacancy_oxidation_state"] = vac.site.specie.oxi_state
    except Exception:
        properties["vacancy_oxidation_state"] = None

    try:
        properties["vacancy_charge_states"] = vac.get_charge_states()
    except Exception:
        properties["vacancy_charge_states"] = None

    try:
        properties["vacancy_multiplicity"] = vac.multiplicity
    except Exception:
        properties["vacancy_multiplicity"] = None

    try:
        properties["vacancy_supercell_formula"] = vac.structure.composition.formula
    except Exception:
        properties["vacancy_supercell_formula"] = None

    try:
        properties["vacancy_name"] = vac.name
    except Exception:
        properties["vacancy_name"] = None

    try:
        properties["vacancy_self_equivalence"] = vac.is_symmetry_equivalent(vac)
    except Exception:
        properties["vacancy_self_equivalence"] = None

    try:
        properties["vacancy_element_changes"] = vac.element_changes
    except Exception:
        properties["vacancy_element_changes"] = None

    try:
        properties["vacancy_latex_name"] = vac.get_latex_string()
    except Exception:
        properties["vacancy_latex_name"] = None

    return properties
